const read = (id) => Number(document.getElementById(id).value);
function update() {
  // In whole cents, so 87.50 with 15% is 100.63, not a float a hair under it.
  const cents = Math.round((Math.round(read("bill") * 100) * (100 + read("tip"))) / 100);
  const total = cents / 100;
  const people = Math.max(1, read("people"));
  let share = Math.round(cents / people) / 100;
  document.getElementById("total").textContent = total.toFixed(2);
  document.getElementById("share").textContent = share.toFixed(2);
  const left = Math.round((share * people - total) * 100) / 100;
  document.getElementById("cent").textContent =
    left === 0 ? "The shares add up to the total." : "The shares come to " + Math.abs(left).toFixed(2) + (left > 0 ? " more" : " less") + " than the total.";
}
document.getElementById("calc").addEventListener("input", update);
update();

